      "첫 범위는 실제 협약 한두 유형과 대상자 확인·프로그램 버전·수행 대조·기업과 개인 부담 분리·청구 승인·정정으로 정할 수 있습니다. 모든 검사 결과 시스템과 국가검진 청구를 한 번에 통합할 필요는 없습니다. 합성 명단과 계약 사례로 개정 전후·중복·한도·부분 미시행·대체·환불을 시험합니다. 원본 계약과 수행·수납 내역을 기준으로 건수와 금액을 대조하고 예외가 자동 확정되지 않는지 확인합니다. 정산 출력에서 상세 임상 결과가 빠지는지도 첫 검수에 포함합니다. 화면의 총액이 맞더라도 개별 부담과 적용 근거가 설명되지 않으면 운영 준비가 끝난 것으로 보지 않습니다."
