      "환자는 이전 계획서를 저장해 두었는데 병원에서는 새 계획으로 안내하면 일정과 비용에 대한 이해가 달라질 수 있습니다. 설명 자료를 열었다는 기록을 충분한 설명이나 동의가 완료된 것으로 오해하는 문제도 피해야 합니다. 한 가족의 계정에서 대상 환자를 바꾸다가 다른 사람의 계획을 보는 경우에는 단순 화면 오류보다 접근 문제가 됩니다. 여러 단계 중 아직 의료진이 확정하지 않은 내용을 자동으로 다음 단계로 표시하면 예정과 결정이 뒤섞입니다. 해결할 대상은 모든 자료를 한 화면에 모으는 것보다 현재 공개 승인본과 변경 이유, 확인할 담당자와 후속 요청 상태를 명확히 보여 주는 일입니다."
