      "환자가 과거 방문의 안내를 현재 방문에 적용하거나 어느 시점에 찍은 사진인지 설명하지 않은 채 문의하면 담당자가 추가 확인을 요청해야 합니다. 사진이 여러 장 올라왔다는 사실과 직원이 내용을 확인했다는 사실은 다릅니다. 자동 접수 메시지를 답변 완료로 표시하면 환자는 더 이상 확인이 필요하지 않다고 오해할 수 있습니다. 상담 채널의 알림에 사진이나 민감한 설명이 그대로 노출되는 문제도 검토해야 합니다. 관리자가 내부 기록을 수정했는데 환자 화면에는 예전 안내가 남는 경우도 생깁니다. 방문·안내·제출·검토의 관계를 연결하고 각 상태의 의미를 정확히 보여 주는 설계가 필요합니다."
