      "기존 예약 시스템이 있다면 홈페이지에서 넘겨줄 의료진·진료과 식별값과 지원되는 주소 규칙을 먼저 확인합니다. 단순 링크 연결은 예약 잔여 시간을 홈페이지에서 보장한다는 뜻이 아닙니다. 시간표를 자료로 받아 표시하려면 갱신 주기와 실패 시의 표시를 예약 운영 담당자와 정합니다. 지도나 영상 서비스에는 외부 연결이 필요하므로 차단 환경에서 주소·전화·텍스트 안내가 남는지도 확인합니다. 검색 기능은 공개 문서만 수집하고 직원용 자료나 로그인 뒤의 환자 정보가 색인에 섞이지 않게 합니다. 기관 내부의 인사 자료 전체를 가져오기보다 공개 승인을 받은 소개 필드만 전달하는 방식이 적합합니다."
