      "원내 삽입·교체·외래 기록에서 실제 확인 가능한 기기 정보를 어떤 형식으로 받을 수 있는지 검토합니다. 제조사 프로그램과 연결하려면 지원 API·계약·장치 목적·안전·규제 조건이 실제로 확인되어야 합니다. 기본 앱은 제조사의 조절기를 대신하거나 명령을 전송하지 않는 정보 확인·보고 범위로 시작할 수 있습니다. 일정·메시지 서비스는 기기와 방문에 맞는 승인 준비 안내를 전달하도록 연결합니다. 외부 자료 저장에는 식별 카드와 건강 정보를 포함할 수 있으므로 접근·보관·반출 조건을 정합니다. 앱에서 표시한 정보만으로 MRI 등 검사 가능 여부나 장치 호환성을 확정하는 기능은 포함하지 않습니다."
