      "환자 두 명의 검사가 연속으로 들어오는 표본에서 이미지 안의 표시와 원내 연결 대상이 맞는지 확인합니다. 여러 장면 영상 중 일부만 변환된 경우 전체 원본과 동일한 자료처럼 표시하지 않아야 합니다. 공개 승인 이후 원본이 정정되면 이전 게시본을 그대로 최신으로 제공하지 않고 영향 확인을 거칩니다. 동반자 공유를 종료한 뒤 기존 링크와 열린 화면에서도 새 자료를 조회할 수 없는지 시험합니다. 한 검사만 공유한 수신자가 이후 다른 진료 목적의 자료까지 보지 못하도록 검수합니다. 통신이 끊긴 동안 오래된 이미지가 화면에 남을 때 현재 상태와 마지막 확인 시점을 정확히 표시하는지도 확인합니다."
