      "여러 검사 장비의 출력물이나 파일을 담당자가 다시 읽어 기록하고 자료를 연결하는 안과가 검토할 수 있습니다. 장비마다 출력 형식이 다르거나 과거 검사 자료를 문서로 받아 비교할 준비가 필요한 경우에 적합합니다. 여기서는 이미 측정된 자료의 정리와 원문 대조를 다루며 영상에서 질환을 진단하거나 수술 결과를 예측하는 AI를 제안하지 않습니다. 구조화된 원본을 받을 수 있다면 문서 인식보다 직접 연결이 더 적합할 수 있으므로 실제 출력 형식을 먼저 확인합니다. 자동화 사용 여부는 명칭이나 유행보다 입력 오류를 줄이고 검토 근거를 남길 수 있는지를 기준으로 결정합니다."
