      "초기에는 본인 일정과 승인 안내, 장소·연락 경로와 변경 목록을 제공하는 앱으로 시작할 수 있습니다. 실제 원내 진행 상태 연결은 지원 여부가 확인된 항목만 포함합니다. 대표 검사와 진료 조합을 선정해 안내가 어느 시점에 바뀌는지 표본으로 시험합니다. 큰 글자·읽기 도구·명확한 대비와 터치 대상은 부가 장식이 아니라 핵심 인수 항목으로 둡니다. 합성 환자 계정으로 보호자 접근과 알림 거절·통신 실패를 확인합니다. 휴대전화만으로 의료 검사를 수행하는 기능이나 자동 결과 해석은 초기 방문 안내 범위에 포함하지 않습니다."
