      "환자가 여러 방문의 검사 자료와 설명을 다시 확인하거나 다른 기관에 제공할 문서를 요청하는 안과가 검토할 수 있는 포털입니다. 문서 파일만 메시지로 전달하면 현재 승인본과 검사 시점, 다른 자료와의 관계를 확인하기 어려운 경우에 적합합니다. 이 범위는 개인별 검사 자료의 공개·조회와 요청을 다루며 원내 장비 수치를 의료진 검토 없이 자동 게시하는 기능이 아닙니다. 환자용 방문 안내 앱과 달리 공개 문서의 버전과 접근·내보내기 기록이 중심입니다. 실제 어떤 자료와 설명을 공개할지, 보호자가 무엇을 볼 수 있을지는 기관의 기준과 담당 승인을 먼저 확인합니다."
