      "기존 안내 동영상을 저장한 환자가 계획 변경 뒤에도 이전 영상을 따라 볼 수 있습니다. 양측 관절을 치료하는 경우 같은 제목의 자료라도 적용 방향이나 시작 시점이 다를 수 있습니다. 수행 버튼을 여러 번 눌렀거나 기기를 바꾼 일이 실제 여러 회차의 수행으로 계산되면 기록이 왜곡됩니다. 하루 기록이 없다는 이유만으로 환자가 안내를 따르지 않았다고 판단하는 것도 적절하지 않습니다. 의료진의 중단 안내가 늦게 반영되면 이미 종료된 계획에 대한 알림이 계속 전달됩니다. 앱은 자료 배정과 현재 적용 상태, 환자의 입력·수정, 담당 검토를 구분하여 이러한 혼동을 확인할 수 있어야 합니다."
