    "adminFeatures": [
      "책임자 화면은 수량 차이·제조번호 미확인·사용 제한·기한 확인이 필요한 제품을 별도로 보여 줍니다. 보관 관련 이상 기록을 받으면 어느 위치와 제품에 영향이 있을 수 있는지 확인할 자료를 제공하되 시스템이 자동으로 사용 가능·불가의 임상적 결론을 내리지 않습니다. 점검 기록이 없다는 상태와 정상 점검을 완료했다는 상태를 구분합니다. 반품·폐기 승인과 실제 처리 결과를 나누고 처리된 수량이 장부에 어떻게 반영됐는지 대조합니다. 회수나 제조사 안내가 있을 경우 해당 제조번호의 현재 위치와 과거 사용 관계를 확인할 수 있는 범위를 검토합니다. 접근·내보내기 권한도 필요 업무에 맞춰 제한합니다."
    ],
    "integrations": [
      "원내 접종 기록과 연결할 때 제품 식별·제조번호·실제 사용 사건의 의미를 확인합니다. 공식 등록 시스템이나 비용 처리 원장과의 연결은 승인된 제공 방식과 권한이 있을 때 범위를 정하며 자동 등록을 기본 전제로 하지 않습니다. 온도 장치가 제공하는 시각·위치·센서 상태와 누락을 확인하고 통신 장애를 정상 온도로 처리하지 않습니다. 납품 자료와 바코드 정보는 실제 제품과 대조할 수 있는 항목만 활용합니다. 예약 시스템에는 전체 재고 대신 기관이 확인한 가용 상태를 제공하도록 검토합니다. 외부 업체별 인터페이스와 장치 지원, 보관·장애 대응 책임은 도입 전에 확인해야 합니다."
    ],
    "dataEntities": [
      "품목과 제품 식별, 제조번호와 사용 기한, 포장·사용 단위를 분리합니다. 재고는 보관 위치와 가용·제한 상태별 수량으로 관리하고 이동 사건이 잔액을 설명하도록 합니다. 입고·배정·사용·배정 해제·반품·폐기·위치 이동·정정은 서로 다른 유형입니다. 실제 사용에는 관련 원내 사건과 확인자를 연결하고 예약 자체와 구분합니다. 보관 점검·장치 측정에는 위치·발생 시각·수신 시각·장치 상태를 남깁니다. 사용 제한과 해제에는 사유·근거·승인자를 기록합니다. 기록을 수정할 때 원래 제조번호나 수량이 사라지지 않도록 이전 값과 정정 사건을 유지해야 합니다."
    ],
    "edgeCases": [
      "같은 품목의 제조번호 두 개를 받아 일부만 사용 제한된 경우 가용 수량이 정확히 나뉘는지 시험합니다. 포장 단위로 입고하고 개별 사용 단위로 차감할 때 승인된 환산과 수량이 맞는지 확인합니다. 임시 배정된 방문이 취소되면 실제 사용되지 않은 수량만 해제되는지 검수합니다. 센서 통신이 끊긴 동안의 공백을 정상 측정으로 채우지 않아야 합니다. 사용 제품의 제조번호를 정정한 경우 두 제조번호의 잔액과 원내 기록 연결이 함께 대조되어야 합니다. 승인된 폐기가 아직 실행되지 않았거나 반품이 거절된 경우 실제 상태와 장부가 다르게 처리되는지도 확인합니다."
    ],
    "mvpScope": [
      "첫 버전은 대표 품목의 제조번호·위치별 입고와 실제 사용, 사용 제한·정정 원장으로 정할 수 있습니다. 자동 온도 연동이나 공식 등록을 포함하지 않더라도 수량과 사용 근거를 정확히 대조하는 흐름을 검증할 수 있습니다. 실제 제품 정보와 형식이 같은 가상 표본으로 복수 제조번호·부분 제한·배정 해제·단위 환산을 시험합니다. 책임자의 승인 없이 사용 제한이 해제되지 않는지 확인합니다. 일일 대조에서 입고·사용·반출·현재 잔액이 설명 가능한지를 인수 기준으로 둡니다. 의료적 사용 판단과 실제 관리 기준은 기관이 확인한 절차로 남깁니다."
    ],
    "expansionScope": [
      "운영 이후 여러 보관 위치와 지점, 온도 장치·납품 문서·예약 가용 조회를 연결할 수 있습니다. 지점 간 이동은 출고와 수령 확인을 나누고 이동 중인 수량이 양쪽 가용 재고에 동시에 잡히지 않도록 합니다. 제조번호 회수 대응은 현재 재고뿐 아니라 과거 사용 관계와 필요한 확인 업무를 조회하는 범위를 검토합니다. 수요 예측을 추가하더라도 실제 의료적 필요나 정부 지원 대상 판단을 자동화하는 기능과 구분합니다. 공식 등록·비용 처리 연동은 권한과 제공 방식이 확인된 별도 범위로 산정합니다. 재고 프로그램이 관리 절차의 준수나 제품 안전을 자동 보증한다고 설명하지 않습니다."
    ],
    "costDrivers": [
      "산정에는 품목·제조번호·보관 위치 수와 단위 환산, 승인·정정 단계가 영향을 줍니다. 수동 점검 기록과 장치 자동 수신은 누락·시간 오차·장애 대응의 검수가 다릅니다. 원내 실제 사용 기록과 납품·예약·공식 등록 연결도 각각 별도 비용 조건입니다. 과거 장부에 제조번호가 없으면 임의로 채울 수 없으므로 이전 범위와 확인 불가 상태를 정해야 합니다. 바코드 장치·센서·메시지·외부 서비스 사용료와 교체·지원 책임도 확인합니다. 견적에는 지원 제품과 상태, 수량 대조 방식과 자동 판단에서 제외하는 항목을 구체적으로 적습니다."
    ],
    "timelineDrivers": [
      "현재 입고·보관·사용·반출 기록과 실제 책임자, 관리 기준을 먼저 확인합니다. 대표 품목의 단위와 제조번호·위치별 이동을 모델링하고 정정·사용 제한 흐름을 검수합니다. 다음으로 원내 사용 기록과 장부 잔액을 같은 표본으로 대조합니다. 온도 장치나 외부 연결은 지원 규격과 승인 환경이 준비된 범위부터 진행합니다. 기존 장부와 병행 확인할 때 이중 차감이나 중복 입고가 생기지 않도록 최종 원장을 명확히 정합니다. 지점·품목을 확대하기 전 새 단위와 제조번호 표현·승인 규칙을 확인하고 장애 중 수기 운영과 복구 절차까지 인수 일정에 포함합니다."
    ],
    "complianceChecks": [
      "제품 보관·취급·사용 제한·반품·폐기의 실제 기준은 현행 공식 지침과 제조사 자료, 기관 절차를 확인해야 합니다. 질병관리청은 예방접종 지침과 접종기관용 보관·관리 자료를 공개하고 있으므로 도입 시 적용할 최신 버전을 확인하는 출발점으로 사용합니다. 이 원고는 특정 보관 온도나 사용 가능 시간을 제시하지 않습니다. HL7 Immunization은 실제 접종 기록과 제품·제조번호 정보를 구분하는 구조를 참고하는 자료이며 공식 등록 승인을 의미하지 않습니다. 환자와 연결되는 사용 기록은 필요한 최소 범위로 처리하고 외부 제공·접근·감사 기록의 책임을 정해야 합니다."
    ],
    "handover": [
      "품목·제조번호·위치·상태별 재고와 이동 유형의 정의를 전달합니다. 운영 담당자는 부분 사용 제한과 임시 배정 해제, 제조번호 정정·반품 거절·폐기 실행을 직접 처리하며 잔액을 대조합니다. 포장·사용 단위와 환산 기준, 장치 측정 누락·시간 차이 표본도 검수 자료로 남깁니다. 사용 제한 해제와 정정의 승인 책임, 공식 자료·제조사 안내가 바뀔 때 확인할 절차를 문서화합니다. 소스·배포·장치·외부 계정·사용료와 백업·복구를 인계합니다. 최종 확인에서는 장부 수량뿐 아니라 실제 사용 사건과 제품 식별이 연결되고 근거 없는 정상 판정이 생성되지 않는지 점검합니다."
    ],
