      "첫 구현은 선정한 일상 활동 목표와 도움·도구·환경을 기록하는 입력, 환자·보호자 출처 구분, 제출·담당 확인으로 정할 수 있습니다. 자동 자세 분석이나 모든 보조기기 연결 없이도 생활 현장의 정보를 전달할 수 있습니다. 실제 대상자가 사용하는 보조 기술과 입력 환경을 좁혀 명시하고 합성 활동 표본으로 끝까지 검수합니다. 수행 상태와 미기록·기술 실패를 구분하고 동일 활동의 조건 차이가 보존되는지 확인합니다. 활동 내용과 안내는 기관이 승인한 자료를 사용합니다. 접근성 기능이 있다는 설명만으로 모든 사용자에게 이용 가능하거나 인증을 받았다고 표현하지 않습니다."
